INSERT INTO ai_call_audit(
    user_id, scenario_code, primary_connection_id, used_connection_id,
    backup_attempted, status, error_code, latency_ms, request_chars,
    response_chars, configuration_snapshot_json, created_at, finished_at
)
VALUES(
    #{userId}, #{scenarioCode}, #{primaryConnectionId}, #{usedConnectionId},
    #{backupAttempted}, #{status}, #{errorCode}, #{latencyMs}, #{requestChars},
    #{responseChars}, #{configurationSnapshotJson}, #{createdAt}, #{finishedAt}
)

mapper.select:
SELECT 
FROM ai_call_audit
WHERE user_id = #{userId}
  AND status <> 'RUNNING'
  AND created_at >= #{from}

SELECT 
FROM ai_call_audit a
LEFT JOIN ai_connection c ON c.id = a.used_connection_id
WHERE a.user_id = #{userId}

    AND a.scenario_code = #{scenarioCode}

ORDER BY a.created_at DESC, a.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM ai_call_audit a
WHERE a.user_id = #{userId}

    AND a.scenario_code = #{scenarioCode}
